flow.set("invadv_rpc_response_topic", msg.rpcResponseTopic);

let operation = msg.operation || 'read';
const params = msg.rpcParams || {};

// Check if any writable field is present
if (params.advancedFunctionWordRaw !== undefined ||
    params.arcFault !== undefined ||
    params.systemSelfCheckEnabled !== undefined ||
    params.generatorPeakShavingEnabled !== undefined ||
    params.gridPeakShavingEnabled !== undefined ||
    params.smartLoadOnGridAlwaysOn !== undefined ||
    params.externalRelayEnabled !== undefined ||
    params.externalMeter !== undefined ||
    params.bmsErrorStopEnabled !== undefined ||
    params.drmEnabled !== undefined ||
    params.parallel !== undefined) {
    operation = 'write';
}

msg.operation = operation;

if (operation === 'write') {
    return [null, msg];
} else {
    return [msg, null];
}

flow.set("invadv_part_sn", null);
flow.set("invadv_part_45", null);
flow.set("invadv_part_280", null);
flow.set("invadv_part_283", null);
flow.set("invadv_part_326", null);
flow.set("invadv_part_417", null);

return msg;

msg.readGroup = "sn";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 3,
    quantity: 5
};
return msg;

msg.readGroup = "reg45";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 45,
    quantity: 1
};
return msg;

msg.readGroup = "reg280";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 280,
    quantity: 4
};
return msg;

msg.readGroup = "reg326";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 326,
    quantity: 2
};
return msg;

msg.readGroup = "reg417";
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 417,
    quantity: 1
};
return msg;

let data = msg.payload;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (!Array.isArray(data)) {
    node.error("Invalid response for " + msg.readGroup);
    return null;
}

const group = msg.readGroup;

if (group === "sn") {
    flow.set("invadv_part_sn", data);
} else if (group === "reg45") {
    flow.set("invadv_part_45", data[0]);
} else if (group === "reg280") {
    flow.set("invadv_part_280", data[0]);  // 280
    flow.set("invadv_part_281", data[1]);  // 281
    flow.set("invadv_part_282", data[2]);  // 282
    flow.set("invadv_part_283", data[3]);  // 283
} else if (group === "reg326") {
    flow.set("invadv_part_326", data[0]);
    flow.set("invadv_part_327", data[1]);
} else if (group === "reg417") {
    flow.set("invadv_part_417", data[0]);
}

// Check if all parts received
const partSn = flow.get("invadv_part_sn");
const part45 = flow.get("invadv_part_45");
const part280 = flow.get("invadv_part_280");
const part326 = flow.get("invadv_part_326");
const part327 = flow.get("invadv_part_327");
const part417 = flow.get("invadv_part_417");

if (!partSn || part45 === null || part45 === undefined ||
    part280 === null || part280 === undefined ||
    part326 === null || part326 === undefined ||
    part327 === null || part327 === undefined ||
    part417 === null || part417 === undefined) {
    return null;
}

msg.snData = partSn;
msg.reg45 = part45;
msg.reg280 = part280;
msg.reg281 = flow.get("invadv_part_281");
msg.reg282 = flow.get("invadv_part_282");
msg.reg283 = flow.get("invadv_part_283");
msg.reg326 = part326;
msg.reg327 = part327;
msg.reg417 = part417;

return msg;

const snData = msg.snData;
const reg45 = msg.reg45;
const reg280 = msg.reg280;
const reg283 = msg.reg283;
const reg326 = msg.reg326;
const reg327 = msg.reg327;
const reg417 = msg.reg417;

// Clear flow context
flow.set("invadv_part_sn", null);
flow.set("invadv_part_45", null);
flow.set("invadv_part_280", null);
flow.set("invadv_part_281", null);
flow.set("invadv_part_282", null);
flow.set("invadv_part_283", null);
flow.set("invadv_part_326", null);
flow.set("invadv_part_327", null);
flow.set("invadv_part_417", null);

// Helper: Parse ASCII
function parseAsciiChar(val, high) {
    const byte = high ? ((val >> 8) & 0xFF) : (val & 0xFF);
    if (byte >= 0x20 && byte <= 0x7E) {
        return String.fromCharCode(byte);
    }
    return '';
}

function parseSerialNumber(regs) {
    let sn = '';
    for (let i = 0; i < 5; i++) {
        sn += parseAsciiChar(regs[i], true);
        sn += parseAsciiChar(regs[i], false);
    }
    return sn.trim();
}

const serialNumber = parseSerialNumber(snData);

// Parse reg280 bit fields
const bit0_3 = reg280 & 0x0F;                    // Microinverter export cutoff
const genPeakShaving = ((reg280 >> 4) & 0x0F);   // Bit4-7: Gen peak-shaving
const gridPeakShaving = ((reg280 >> 8) & 0x0F); // Bit8-11: Grid peak-shaving
const onGridAlwaysOn = ((reg280 >> 12) & 0x01); // Bit12: On Grid always on
const externalRelay = ((reg280 >> 13) & 0x01);  // Bit13: external relay
const bmsErrorStop = ((reg280 >> 14) & 0x01);   // Bit14: BMS error stop
const drmEnabled = ((reg280 >> 15) & 0x01);     // Bit15: DRM enable

// Parse reg283: Arc Fault Mode
// 0=close, 1=open, 2=clear request
const arcFaultEnabled = (reg283 === 1);
const arcFaultClearRequested = (reg283 === 2);

// Parse reg45: Self-checking time (0-360 seconds)
// 0 = disabled, >0 = enabled with time
const selfCheckTime = reg45;
const systemSelfCheckEnabled = reg45 > 0;

// Parse reg326: External meter phase (Bit1-3 = A/B/C phase)
const phaseA = ((reg326 >> 1) & 0x01) === 1;
const phaseB = ((reg326 >> 2) & 0x01) === 1;
const phaseC = ((reg326 >> 3) & 0x01) === 1;
let phaseStr = '';
if (phaseA) phaseStr += 'A';
if (phaseB) phaseStr += 'B';
if (phaseC) phaseStr += 'C';
if (!phaseStr) phaseStr = null;

// Parse reg327: CT ratio (200-8000)
const ctRatio = reg327;

// Parse reg417: Parallel settings
const parallelEnabled = (reg417 & 0x01) === 1;        // Bit0
const parallelIsMaster = ((reg417 >> 1) & 0x01) === 1; // Bit1
const parallelModbusAddr = (reg417 >> 10) & 0x3F;      // Bit10-15

let parallelRole = 'standalone';
if (parallelEnabled) {
    parallelRole = parallelIsMaster ? 'master' : 'slave';
}

const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";

const state = {
    kind: "InverterAdvancedFunctionConfigState",
    timestampUtc: new Date().toISOString(),
    gatewayId: gatewayId,
    inverterSerialNumber: serialNumber,
    version: "1.0",

    advancedFunctionWordRaw: reg280,

    arcFault: {
        enabled: arcFaultEnabled,
        clearRequested: arcFaultClearRequested
    },

    systemSelfCheckEnabled: systemSelfCheckEnabled,
    selfCheckTimeSeconds: selfCheckTime,

    generatorPeakShavingEnabled: genPeakShaving === 1,
    gridPeakShavingEnabled: gridPeakShaving === 1,

    smartLoadOnGridAlwaysOn: onGridAlwaysOn === 1,
    externalRelayEnabled: externalRelay === 1,
    islandModeSignalEnabled: null,  // Derived - not directly readable

    externalMeter: {
        ctRatio: ctRatio,
        phase: phaseStr
    },

    bmsErrorStopEnabled: bmsErrorStop === 1,
    drmEnabled: drmEnabled === 1,

    parallel: {
        enabled: parallelEnabled,
        role: parallelRole,
        modbusAddress: parallelModbusAddr
    },

    rawRegisters: {
        reg45: reg45,
        reg280: reg280,
        reg283: reg283,
        reg326: reg326,
        reg327: reg327,
        reg417: reg417
    }
};

// Check if this is after a write
const writeResult = flow.get("invadv_write_result");
flow.set("invadv_write_result", null);

const rpcResponseTopic = flow.get("invadv_rpc_response_topic");
flow.set("invadv_rpc_response_topic", null);

if (writeResult) {
    msg.payload = {
        success: true,
        message: `Successfully wrote ${writeResult.count} register(s)`,
        writes: writeResult.writes,
        state: state
    };
} else {
    msg.payload = state;
}

msg.rpcResponseTopic = rpcResponseTopic;

return msg;

if (!msg.rpcResponseTopic) {
    return null;
}

msg.topic = msg.rpcResponseTopic;
return msg;

const params = msg.rpcParams || {};
const writes = [];

// Store current reg280 for bit manipulation
let reg280Current = flow.get("invadv_part_280") || 0;

// 045: systemSelfCheckEnabled (0-360 seconds)
if (params.systemSelfCheckEnabled !== undefined) {
    // If true, set to default 60 seconds, if false set to 0
    let val = 0;
    if (params.systemSelfCheckEnabled === true) {
        val = params.selfCheckTimeSeconds || 60;
    } else if (typeof params.systemSelfCheckEnabled === 'number') {
        val = params.systemSelfCheckEnabled;
    }
    val = Math.max(0, Math.min(360, val));
    writes.push({ register: 45, value: val, name: "Self Check Time" });
}

if (params.selfCheckTimeSeconds !== undefined) {
    const val = Math.max(0, Math.min(360, params.selfCheckTimeSeconds));
    writes.push({ register: 45, value: val, name: "Self Check Time" });
}

// 283: arcFault
if (params.arcFault !== undefined) {
    let val = 0;  // close
    if (params.arcFault.enabled === true) val = 1;  // open
    if (params.arcFault.clearRequested === true) val = 2;  // clear
    writes.push({ register: 283, value: val, name: "Arc Fault Mode" });
}

// 327: CT ratio
if (params.externalMeter && params.externalMeter.ctRatio !== undefined) {
    const val = Math.max(200, Math.min(8000, params.externalMeter.ctRatio));
    writes.push({ register: 327, value: val, name: "CT Ratio" });
}

// 326: External meter phase (need to read first for bit manipulation)
if (params.externalMeter && params.externalMeter.phase !== undefined) {
    let reg326Current = flow.get("invadv_part_326") || 0;
    const phaseStr = params.externalMeter.phase.toUpperCase();

    // Clear bits 1-3
    reg326Current &= ~0x0E;

    if (phaseStr.includes('A')) reg326Current |= (1 << 1);
    if (phaseStr.includes('B')) reg326Current |= (1 << 2);
    if (phaseStr.includes('C')) reg326Current |= (1 << 3);

    writes.push({ register: 326, value: reg326Current, name: "Meter Phase" });
}

// 280 bit fields - need to manipulate individual bits
let needWrite280 = false;

if (params.generatorPeakShavingEnabled !== undefined) {
    reg280Current &= ~(0x0F << 4);  // Clear Bit4-7
    if (params.generatorPeakShavingEnabled) {
        reg280Current |= (1 << 4);  // Set Bit4
    }
    needWrite280 = true;
}

if (params.gridPeakShavingEnabled !== undefined) {
    reg280Current &= ~(0x0F << 8);  // Clear Bit8-11
    if (params.gridPeakShavingEnabled) {
        reg280Current |= (1 << 8);  // Set Bit8
    }
    needWrite280 = true;
}

if (params.smartLoadOnGridAlwaysOn !== undefined) {
    if (params.smartLoadOnGridAlwaysOn) {
        reg280Current |= (1 << 12);
    } else {
        reg280Current &= ~(1 << 12);
    }
    needWrite280 = true;
}

if (params.externalRelayEnabled !== undefined) {
    if (params.externalRelayEnabled) {
        reg280Current |= (1 << 13);
    } else {
        reg280Current &= ~(1 << 13);
    }
    needWrite280 = true;
}

if (params.bmsErrorStopEnabled !== undefined) {
    if (params.bmsErrorStopEnabled) {
        reg280Current |= (1 << 14);
    } else {
        reg280Current &= ~(1 << 14);
    }
    needWrite280 = true;
}

if (params.drmEnabled !== undefined) {
    if (params.drmEnabled) {
        reg280Current |= (1 << 15);
    } else {
        reg280Current &= ~(1 << 15);
    }
    needWrite280 = true;
}

if (params.advancedFunctionWordRaw !== undefined) {
    reg280Current = params.advancedFunctionWordRaw;
    needWrite280 = true;
}

if (needWrite280) {
    writes.push({ register: 280, value: reg280Current, name: "Advanced Function Word" });
}

// 417: Parallel settings
if (params.parallel !== undefined) {
    let reg417Current = flow.get("invadv_part_417") || 0;

    if (params.parallel.enabled !== undefined) {
        if (params.parallel.enabled) {
            reg417Current |= 0x01;  // Set Bit0
        } else {
            reg417Current &= ~0x01;  // Clear Bit0
        }
    }

    if (params.parallel.role !== undefined) {
        if (params.parallel.role === 'master') {
            reg417Current |= (1 << 1);  // Set Bit1
        } else {
            reg417Current &= ~(1 << 1);  // Clear Bit1
        }
    }

    if (params.parallel.modbusAddress !== undefined) {
        reg417Current &= ~(0x3F << 10);  // Clear Bit10-15
        const addr = Math.max(0, Math.min(63, params.parallel.modbusAddress));
        reg417Current |= (addr << 10);
    }

    writes.push({ register: 417, value: reg417Current, name: "Parallel Settings" });
}

if (writes.length === 0) {
    node.warn("No valid parameters to write");
    return null;
}

global.set("invadv_write_queue", writes);
global.set("invadv_write_index", 0);
global.set("invadv_write_results", []);

node.status({ fill: "blue", shape: "dot", text: writes.length + " writes queued" });

return msg;

// Read 280 and 326 and 417 first for bit manipulation
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 280,
    quantity: 4
};
msg.readStep = 1;
return msg;

let data = msg.payload;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (msg.readStep === 1) {
    // Store 280-283
    flow.set("invadv_part_280", data[0]);
    flow.set("invadv_part_281", data[1]);
    flow.set("invadv_part_282", data[2]);
    flow.set("invadv_part_283", data[3]);

    // Read 326-327
    msg.payload = {
        fc: 3,
        unitid: 1,
        address: 326,
        quantity: 2
    };
    msg.readStep = 2;
    return [msg, null];
} else if (msg.readStep === 2) {
    flow.set("invadv_part_326", data[0]);
    flow.set("invadv_part_327", data[1]);

    // Read 417
    msg.payload = {
        fc: 3,
        unitid: 1,
        address: 417,
        quantity: 1
    };
    msg.readStep = 3;
    return [msg, null];
} else if (msg.readStep === 3) {
    flow.set("invadv_part_417", data[0]);

    // Now update write queue with current values
    const writes = global.get("invadv_write_queue") || [];
    const params = msg.rpcParams || {};
    let reg280Current = flow.get("invadv_part_280") || 0;

    // Re-apply bit changes to reg280 with fresh data
    for (let i = 0; i < writes.length; i++) {
        if (writes[i].register === 280) {
            let newVal = reg280Current;

            if (params.generatorPeakShavingEnabled !== undefined) {
                newVal &= ~(0x0F << 4);
                if (params.generatorPeakShavingEnabled) newVal |= (1 << 4);
            }
            if (params.gridPeakShavingEnabled !== undefined) {
                newVal &= ~(0x0F << 8);
                if (params.gridPeakShavingEnabled) newVal |= (1 << 8);
            }
            if (params.smartLoadOnGridAlwaysOn !== undefined) {
                if (params.smartLoadOnGridAlwaysOn) newVal |= (1 << 12);
                else newVal &= ~(1 << 12);
            }
            if (params.externalRelayEnabled !== undefined) {
                if (params.externalRelayEnabled) newVal |= (1 << 13);
                else newVal &= ~(1 << 13);
            }
            if (params.bmsErrorStopEnabled !== undefined) {
                if (params.bmsErrorStopEnabled) newVal |= (1 << 14);
                else newVal &= ~(1 << 14);
            }
            if (params.drmEnabled !== undefined) {
                if (params.drmEnabled) newVal |= (1 << 15);
                else newVal &= ~(1 << 15);
            }
            if (params.advancedFunctionWordRaw !== undefined) {
                newVal = params.advancedFunctionWordRaw;
            }

            writes[i].value = newVal;
        }

        if (writes[i].register === 326 && params.externalMeter && params.externalMeter.phase) {
            let reg326Current = flow.get("invadv_part_326") || 0;
            const phaseStr = params.externalMeter.phase.toUpperCase();
            reg326Current &= ~0x0E;
            if (phaseStr.includes('A')) reg326Current |= (1 << 1);
            if (phaseStr.includes('B')) reg326Current |= (1 << 2);
            if (phaseStr.includes('C')) reg326Current |= (1 << 3);
            writes[i].value = reg326Current;
        }

        if (writes[i].register === 417 && params.parallel) {
            let reg417Current = flow.get("invadv_part_417") || 0;
            if (params.parallel.enabled !== undefined) {
                if (params.parallel.enabled) reg417Current |= 0x01;
                else reg417Current &= ~0x01;
            }
            if (params.parallel.role !== undefined) {
                if (params.parallel.role === 'master') reg417Current |= (1 << 1);
                else reg417Current &= ~(1 << 1);
            }
            if (params.parallel.modbusAddress !== undefined) {
                reg417Current &= ~(0x3F << 10);
                const addr = Math.max(0, Math.min(63, params.parallel.modbusAddress));
                reg417Current |= (addr << 10);
            }
            writes[i].value = reg417Current;
        }
    }

    global.set("invadv_write_queue", writes);

    // Proceed to write
    return [null, msg];
}

return null;

const writes = global.get("invadv_write_queue") || [];
const index = global.get("invadv_write_index") || 0;

if (index >= writes.length) {
    return null;
}

const current = writes[index];

msg.payload = {
    fc: 16,
    unitid: 1,
    address: current.register,
    quantity: 1,
    value: [current.value]
};
msg.currentWrite = current;

node.status({ fill: "blue", shape: "dot", text: `[${index+1}/${writes.length}] ${current.name}` });

return msg;

const writes = global.get("invadv_write_queue") || [];
let index = global.get("invadv_write_index") || 0;
const results = global.get("invadv_write_results") || [];

const current = msg.currentWrite;
if (current) {
    results.push({
        register: current.register,
        name: current.name,
        value: current.value,
        success: true
    });
    global.set("invadv_write_results", results);
}

index++;
global.set("invadv_write_index", index);

node.status({ fill: "green", shape: "dot", text: `${current.name} OK` });

if (index < writes.length) {
    return [msg, null];
}

// All writes done
flow.set("invadv_write_result", {
    count: results.length,
    writes: results
});

global.set("invadv_write_queue", null);
global.set("invadv_write_index", null);
global.set("invadv_write_results", null);

return [null, msg];
